insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Spencer Flooring & Paint','Home Services','Tracy','475 W Grant Line Road, Tracy, CA 95376','(209) 835-5537','https://www.spencerflooringandpaint.com/','Tracy flooring showroom advertising carpet installation/removal and painting services. Official contact page lists 475 W Grant Line Road and Saturday visits by appointment. Confirm job location, scope, current hours, quote and scheduling directly. Coverage beyond Tracy not independently established.','approved',true,false,null,0,'editorial_first_party','https://www.spencerflooringandpaint.com/aboutus.aspx','first_party_website_desk_check',now()) returning id into bid;
