insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Pickleball Courts Grand Opening & Ribbon Cutting','City-listed opening of the new pickleball courts at Central Community Park, with remarks, a ribbon cutting and pickleball activities. All ages welcome; RSVP through the City. Official Form Center lists November 18, 2026 at 4:30 PM. Confirm construction/weather changes and arrangements directly; end time not established.','Mountain House','Central Community Park, Mountain House','2026-11-18T16:30:00-08:00',null,'Community programs','https://www.mountainhouseca.gov/FormCenter/RSVPs-8/Pickleball-Courts-Ribbon-Cutting-RSVP-71','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where (source_url='https://www.mountainhouseca.gov/FormCenter/RSVPs-8/Pickleball-Courts-Ribbon-Cutting-RSVP-71' or title ilike '%pickleball%') and start_date='2026-11-18T16:30:00-08:00'::timestamptz);
